import{_ as i,C as n,o as s,c as d,j as t,a,b as l,w as r,E as c,a4 as h,a3 as p}from"./chunks/framework.DhF4LrUq.js";const A=JSON.parse('{"title":"Feedback and analytics","description":"Feedback and analytics - tester reports, device events, and the closed loop from metrics to gates to promotion.","frontmatter":{"description":"Feedback and analytics - tester reports, device events, and the closed loop from metrics to gates to promotion."},"headers":[],"relativePath":"concepts/feedback-analytics.md","filePath":"concepts/feedback-analytics.md"}'),u={name:"concepts/feedback-analytics.md"};function b(m,e,g,f,y,v){const o=n("Mermaid");return s(),d("div",null,[e[1]||(e[1]=t("h1",{id:"feedback-and-analytics",tabindex:"-1"},[a("Feedback and analytics "),t("a",{class:"header-anchor",href:"#feedback-and-analytics","aria-label":'Permalink to "Feedback and analytics"'},"​")],-1)),e[2]||(e[2]=t("p",null,'ShipperDog closes the loop between "we shipped a build" and "is it any good": testers report issues, devices report events, the platform turns both into metrics, and the metrics are what quality gates and promotion policies read. Widening a release is decided by evidence, not optimism.',-1)),e[3]||(e[3]=t("h2",{id:"the-loop",tabindex:"-1"},[a("The loop "),t("a",{class:"header-anchor",href:"#the-loop","aria-label":'Permalink to "The loop"'},"​")],-1)),(s(),l(h,null,{default:r(()=>[c(o,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20INSTALL%5B%22Tester%20installs%3Cbr%2F%3Efrom%20the%20Portal%22%5D%0A%20%20%20%20SDK%5B%22Telemetry%20SDK%20in%20the%20build%3Cbr%2F%3Einstalls%2C%20sessions%2C%20crashes%2C%3Cbr%2F%3Euninstalls%2C%20verdicts%22%5D%0A%20%20%20%20REPORT%5B%22Tester%20feedback%3Cbr%2F%3Ebug%2C%20crash%2C%20UX%20issue%2C%3Cbr%2F%3Efeature%20request%2C%3Cbr%2F%3Esecurity%20issue%22%5D%0A%20%20%20%20TRIAGE%5B%22QA%20triage%3Cbr%2F%3Eseverity%2C%20assignee%2C%3Cbr%2F%3Elifecycle%22%5D%0A%20%20%20%20METRICS%5B%22Release%20analytics%3Cbr%2F%3Ecrash-free%20sessions%2C%20install%20success%2C%3Cbr%2F%3Eengagement%2C%20open%20critical%20bugs%22%5D%0A%20%20%20%20GATES%5B%22Quality%20gates%3Cbr%2F%3Ecrash-free-threshold%2C%3Cbr%2F%3Eopen-critical-bugs%22%5D%0A%20%20%20%20RULES%5B%22Release%20policies%3Cbr%2F%3E(BLOCK%20%2F%20HOLD%20rules%3Cbr%2F%3Eover%20metrics)%22%5D%0A%20%20%20%20PROMOTE%5B%22Ring%20promotion%3Cbr%2F%3Ethe%20next%2C%20wider%20audience%22%5D%0A%20%20%20%20WIDER%5B%22More%20testers%20on%20more%20rings%3Cbr%2F%3Emore%20feedback%2C%20more%20data%22%5D%0A%0A%20%20%20%20INSTALL%20--%3E%20SDK%0A%20%20%20%20INSTALL%20--%3E%20REPORT%0A%20%20%20%20SDK%20--%3E%20METRICS%0A%20%20%20%20REPORT%20--%3E%20TRIAGE%20--%3E%20METRICS%0A%20%20%20%20METRICS%20--%3E%20GATES%20--%3E%20PROMOTE%0A%20%20%20%20METRICS%20--%3E%20RULES%20--%3E%20PROMOTE%0A%20%20%20%20PROMOTE%20--%3E%20WIDER%20--%3E%20INSTALL%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=p('<h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p>Testers submit one of six report types — bug, feedback, crash, feature request, UX issue, security issue — from the portal (or from inside the app, via the SDK&#39;s handoff). The platform attaches the context automatically: application, version, build, tenant, tester, device, OS, and the release being evaluated. Attachments (screenshots, videos, logs) ride along.</p><p>QA works the queue: severity (<code>CRITICAL</code> / <code>MAJOR</code> / <code>MINOR</code>) is assigned at triage, reports are assigned and move through a lifecycle (<code>OPEN</code> to <code>TRIAGED</code> to <code>RESOLVED</code> or <code>REJECTED</code>, re-openable), and closing crossings carry a mandatory note. Security-issue reports have restricted visibility — below the security bar, they conceal as if they did not exist, in listings, details, and counts alike.</p><p>The number that gates promotions: <strong>open critical bugs</strong> — the count of unresolved critical reports for the release, computed live. A promotion into a ring whose gate demands zero refuses while any critical report is unresolved; resolve it and the next attempt passes.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>The metric dictionary, computed per release (and per ring in the rollups):</p><table tabindex="0"><thead><tr><th>Metric</th><th>What it is</th></tr></thead><tbody><tr><td>Downloads</td><td>Allowed download issuances — internal, day one</td></tr><tr><td>Installations</td><td><code>INSTALL</code> events from devices</td></tr><tr><td>Install success rate</td><td>Succeeded installs over reported installs</td></tr><tr><td>Crash-free sessions</td><td>1 minus crash sessions over total sessions</td></tr><tr><td>ANR rate</td><td>Application-not-responding sessions over total</td></tr><tr><td>Uninstall rate</td><td>Uninstalls over installs</td></tr><tr><td>Tester engagement</td><td>Targeted testers who downloaded over targeted testers</td></tr><tr><td>Approval duration</td><td>Average time to decide approval rounds</td></tr><tr><td>Time in ring</td><td>How long the release has occupied its ring</td></tr></tbody></table><p>Two rules govern honesty here:</p><ul><li><strong>No data is not zero and not a pass.</strong> A metric with no device events yet answers <code>NO_DATA</code> — shown distinctly from a failure, but it blocks whatever demanded it, all the same, until data arrives or the governed override applies.</li><li><strong>Rates never sum.</strong> Counts aggregate; rates recompute at every grain — the dashboards fold series accordingly.</li></ul><h2 id="the-telemetry-sdk" tabindex="-1">The telemetry SDK <a class="header-anchor" href="#the-telemetry-sdk" aria-label="Permalink to &quot;The telemetry SDK&quot;">​</a></h2><p>The metrics that need device-side facts come from a small, dependency- free SDK embedded in test builds (Android ~36 KB, iOS ~183 KB): it reports install confirmations, session summaries with crash/ANR counts, uninstalls, and the tester&#39;s verdict, batching offline with deduplication. It pairs with the download that delivered the build — the portal&#39;s install dialog surfaces the token — and it never replaces your crash tooling: it is a beacon for release evidence, not another Sentry. In-app feedback hands off to the portal with the crash summary prefilled; nothing posts itself.</p><h2 id="where-the-numbers-surface" tabindex="-1">Where the numbers surface <a class="header-anchor" href="#where-the-numbers-surface" aria-label="Permalink to &quot;Where the numbers surface&quot;">​</a></h2><ul><li><strong>The release dashboard</strong> — current dictionary per release, beside the gates, approvals, and timelines.</li><li><strong>The organization and tenant dashboards</strong> — counts, per-application release health, pending actions, and downloads-per-day charts.</li><li><strong>The OTA dashboard</strong> — the update funnel for OTA-enabled applications: checks counted server-side, the download-apply journey device-reported (<a href="/shipperdog/snapshot/concepts/ota-updates">OTA updates</a>).</li><li><strong>Gates and policies</strong> — the two engines above.</li></ul><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/approvals-gates">Approvals and gates</a> — what the metrics feed</li><li><a href="/shipperdog/snapshot/concepts/rings-and-rollout">Rings and rollout</a> — what the gates unlock</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/analytics.md" target="_blank" rel="noreferrer">analytics</a>, <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/dashboards.md" target="_blank" rel="noreferrer">dashboards</a>, and <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/telemetry-sdk.md" target="_blank" rel="noreferrer">telemetry SDK</a> docs.</li></ul>',15))])}const T=i(u,[["render",b]]);export{A as __pageData,T as default};
